document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(editState&&(b.dataset.page||b.dataset.recipe||b.dataset.recipeTab||b.dataset.action)){event.preventDefault();editMessage('Termina o cancela el borrador antes de salir.');return;}if(b.dataset.page){ui.page=b.dataset.page;ui.agent=null;ui.process=null;if(ui.page==='recetas'){ui.recipe=null;ui.recipeTab='infografia'}}else if(b.dataset.openAgent){ui.page='agentes';ui.agent=b.dataset.openAgent}else if(b.dataset.openProcess){ui.page='procesos';ui.process=b.dataset.openProcess}else if(b.dataset.recipe){ui.recipe=b.dataset.recipe;ui.recipeTab='infografia';ui.zoom=1}else if(b.dataset.recipeTab){ui.recipeTab=b.dataset.recipeTab}else if(b.dataset.action==='back-recipes'){ui.recipe=null;ui.recipeTab='infografia'}else if(b.dataset.action==='schema'){ui.recipe=null;ui.recipeTab='schema'}else if(b.dataset.listPage){ui.pageNumber=Number(b.dataset.listPage)}else if(b.dataset.zoom){if(b.dataset.zoom==='fit')ui.zoom=1;else ui.zoom=Math.max(1,Math.min(2,ui.zoom+(b.dataset.zoom==='in'?.25:-.25)));const svg=document.querySelector('.diagram-svg');if(svg){svg.setAttribute('width',Number(svg.dataset.baseWidth)*ui.zoom);svg.setAttribute('height',Number(svg.dataset.baseHeight)*ui.zoom);$('zoom-label').textContent=`${Math.round(ui.zoom*100)} % · desplaza horizontalmente si es necesario`}return}else return;render();const heading=$('content').querySelector('h1');if(heading)heading.focus({preventScroll:true});window.scrollTo(0,0);});
